from composio import Composio

logging.basicConfig(filename='/home/user/multi_exec.log', level=logging.INFO)

try:
    with open('/logs/trial_id', 'r') as f:
        trial_id = f.read().strip()
except Exception as e:
    trial_id = "multi_execute_github_slack_pytho__pc35TV5"

client = Composio()
user_id = "zealt-user01"

repo_name = f"multi-test-{trial_id}"
owner = "zealt-user01"

tools_payload = [
    {
        'tool_slug': 'GITHUB_CREATE_OR_UPDATE_FILE_CONTENTS',
        'arguments': {
            'owner': owner,
            'repo': repo_name,
            'path': 'harbor.txt',
            'message': f'Update harbor.txt for trial {trial_id}',
            'content': f'Harbor trial {trial_id}'
        }
    },
    {
        'tool_slug': 'SLACK_CHAT_POST_MESSAGE',
        'arguments': {
            'channel': 'general',
            'text': f'File harbor.txt created in trial {trial_id}'
        }
    }
]

logging.info("Executing COMPOSIO_MULTI_EXECUTE_TOOL...")
try:
    res = client.tools.execute(
        slug='COMPOSIO_MULTI_EXECUTE_TOOL',
        arguments={
            'tools': tools_payload,
            'sync_response_to_workbench': False
        },
        user_id=user_id,
        dangerously_skip_version_check=True
    )
    logging.info(f"Execution Result: {json.dumps(res, indent=2)}")
    print("Multi-execution successful.")
except Exception as e:
    logging.error(f"Execution Error: {e}")
